import string as _string

import pytest
from hypothesis import given, HealthCheck
from hypothesis.strategies import sampled_from, text, integers, lists

from solution import make_palindrome, is_palindrome


# ---------- obviously-correct reference model ----------

def ref_longest_suffix_start(s: str) -> int:
    """Smallest i such that s[i:] is a palindrome (longest palindromic suffix)."""
    for i in range(len(s) + 1):
        if s[i:] == s[i:][::-1]:
            return i
    return len(s)  # unreachable; empty suffix is palindrome


def ref_make_palindrome(s: str) -> str:
    i = ref_longest_suffix_start(s)
    return s + s[:i][::-1]


def exists_palindrome_with_prefix(s: str, L: int) -> bool:
    """Whether there exists any palindrome of length L beginning with s."""
    if L < len(s):
        return False
    p = [None] * L
    for idx, ch in enumerate(s):
        p[idx] = ch
    for idx in range(L):
        j = L - 1 - idx
        a, b = p[idx], p[j]
        if a is not None and b is not None and a != b:
            return False
        if a is not None:
            p[j] = a
        elif b is not None:
            p[idx] = b
    return True


