@given(STRATEGY)
def test_matches_reference_model(s):
    assert make_palindrome(s) == ref_make_palindrome(s)


@given(STRATEGY)
def test_is_shortest_palindrome_with_prefix(s):
    r = make_palindrome(s)
    # no strictly shorter length can host a palindrome starting with s
    for L in range(len(s), len(r)):
        assert not exists_palindrome_with_prefix(s, L), (
            f"s={s!r} result={r!r} but shorter length {L} is feasible"
        )
    # result length itself is feasible (it is a palindrome with prefix)
    assert exists_palindrome_with_prefix(s, len(r))


@given(STRATEGY)
def test_uses_longest_palindromic_suffix(s):
    r = make_palindrome(s)
    assert r[len(s):] == r[:len(s) - (len(r) - len(s))][::-1] if len(r) > len(s) else r == s
    # the added part must be reverse of prefix before palindromic suffix
    added = len(r) - len(s)
    if added > 0:
        prefix = s[:len(s) - added]
        assert r == s + prefix[::-1]
        # suffix left over must be palindrome
        assert is_palindrome(s[len(s) - added:])
    else:
        assert is_palindrome(s)


@given(STRATEGY)
def test_suffix_is_longest_palindromic_suffix(s):
    r = make_palindrome(s)
    added = len(r) - len(s)
    i = len(s) - added
    # s[i:] must be palindrome
    assert is_palindrome(s[i:])
    # no smaller i gives palindromic suffix (longest)
    for j in range(i):
        assert not is_palindrome(s[j:])


